```js
import { test } from "node:test";
import assert from "node:assert/strict";
import { anularFactura } from "../src/factura.mjs";

const original = Object.freeze({ numero: 1, estado: "emitida", totalCentavos: 1000 });

test("RF-005: la anulación sin motivo se rechaza", () => {
  assert.throws(() => anularFactura(original), /motivo/);
  assert.throws(() => anularFactura(original, ""), /motivo/);
  assert.throws(() => anularFactura(original, 42), /motivo/);
});

test("RF-005: un motivo de solo espacios se rechaza", () => {
  assert.throws(() => anularFactura(original, "   "), /motivo/);
  assert.throws(() => anularFactura(original, "\t\n "), /motivo/);
});

test("RF-005: con motivo devuelve una factura nueva anulada y no altera la original", () => {
  const anulada = anularFactura(original, "  error de NIT  ");
  assert.notEqual(anulada, original);
  assert.equal(anulada.estado, "anulada");
  assert.equal(anulada.motivoAnulacion, "error de NIT");
  assert.ok(Object.isFrozen(anulada));
  assert.equal(original.estado, "emitida");
  assert.equal("motivoAnulacion" in original, false);
});
```

